arguments.file_text:
namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    private readonly object _lock = new();

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new Recipe
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a weekend morning.",
                Ingredients = new List<string> { "1½ cups flour", "3½ tsp baking powder", "1 tbsp sugar", "1¼ cups milk", "1 egg", "3 tbsp melted butter" },
                Steps = new List<string> { "Mix dry ingredients in a bowl.", "Make a well and pour in milk, egg, and butter.", "Mix until smooth.", "Cook on a hot griddle until bubbles form, then flip.", "Serve with syrup and fresh fruit." }
            },
            new Recipe
            {
                Id = 2, Title = "Veggie Omelette", Category = "Breakfast",
                Description = "A hearty omelette packed with fresh vegetables and cheese.",
                Ingredients = new List<string> { "3 eggs", "¼ cup diced bell pepper", "¼ cup diced onion", "¼ cup shredded cheese", "Salt and pepper", "1 tbsp butter" },
                Steps = new List<string> { "Beat eggs with salt and pepper.", "Melt butter in a skillet over medium heat.", "Pour in eggs and let set slightly.", "Add vegetables and cheese to one half.", "Fold omelette and cook until cheese melts." }
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Description = "A rich and savory Italian meat sauce served over spaghetti.",
                Ingredients = new List<string> { "1 lb ground beef", "1 can crushed tomatoes", "1 onion, diced", "3 cloves garlic", "1 lb spaghetti", "2 tbsp olive oil", "Salt, pepper, Italian seasoning" },
                Steps = new List<string> { "Cook spaghetti according to package directions.", "Sauté onion and garlic in olive oil.", "Brown the ground beef and drain fat.", "Add tomatoes and seasonings, simmer 20 minutes.", "Serve sauce over spaghetti." }
            },
            new Recipe
            {
                Id = 4, Title = "Grilled Chicken Tacos", Category = "Dinner",
                Description = "Smoky grilled chicken in warm tortillas with fresh toppings.",
                Ingredients = new List<string> { "2 chicken breasts", "8 small tortillas", "1 cup salsa", "1 avocado", "½ cup sour cream", "Lime wedges", "Cumin, chili powder, salt" },
                Steps = new List<string> { "Season chicken with cumin, chili powder, and salt.", "Grill chicken until cooked through, about 6 min per side.", "Slice chicken into strips.", "Warm tortillas on the grill.", "Assemble tacos with chicken, salsa, avocado, and sour cream." }
            },
            new Recipe
            {
                Id = 5, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Classic chewy chocolate chip cookies with a crispy edge.",
                Ingredients = new List<string> { "2¼ cups flour", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "1 tsp vanilla", "1 tsp baking soda", "2 cups chocolate chips" },
                Steps = new List<string> { "Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheets.", "Bake at 375°F for 9-11 minutes." }
            },
            new Recipe
            {
                Id = 6, Title = "Strawberry Cheesecake", Category = "Desserts",
                Description = "Creamy New York-style cheesecake topped with fresh strawberries.",
                Ingredients = new List<string> { "2 lbs cream cheese", "¾ cup sugar", "5 eggs", "2 tsp vanilla", "1 cup graham cracker crumbs", "¼ cup melted butter", "1 lb fresh strawberries" },
                Steps = new List<string> { "Mix crumbs and butter, press into springform pan.", "Beat cream cheese and sugar until smooth.", "Add eggs one at a time, then vanilla.", "Pour over crust and bake at 325°F for 60 minutes.", "Cool completely, top with sliced strawberries." }
            }
        };
        _nextId = 7;
    }

    public List<string> GetCategories()
    {
        lock (_lock)
        {
