@page "/recipes"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>Browse Recipes</PageTitle>

<h1>Browse Recipes</h1>
<p class="text-muted">Choose a category to explore recipes.</p>

<div class="row">
    @foreach (var category in RecipeService.GetCategories())
    {
        var recipes = RecipeService.GetByCategory(category);
        <div class="col-md-4 mb-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h4 class="card-title">@category</h4>
                    <p class="card-text">@recipes.Count recipe(s)</p>
                    <a href="/recipes/@category" class="btn btn-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@page "/recipes/{CategoryName}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<h1>@CategoryName Recipes</h1>
<p><a href="/recipes" class="text-decoration-none">&larr; All Categories</a></p>

@if (recipes.Any())
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <p class="text-muted small">
                            @if (recipe.TotalRatings > 0)
                            {
                                <span>★ @recipe.AverageRating.ToString("0.0") (@recipe.TotalRatings ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <div class="alert alert-info">No recipes found in this category.</div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = "";
    private List<RecipeShare.Models.Recipe> recipes = new();

    protected override void OnInitialized()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

@if (recipe is not null)
{
    <PageTitle>@recipe.Title - RecipeShare</PageTitle>

    <p><a href="/recipes/@recipe.Category" class="text-decoration-none">&larr; Back to @recipe.Category</a></p>

    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: @recipe.Category</p>

    @if (!string.IsNullOrEmpty(recipe.Description))
    {
        <p class="lead">@recipe.Description</p>
    }

    <div class="mb-4">
        <h4>Rating</h4>
        <StarRating RecipeId="@recipe.Id"
                    CurrentRating="@recipe.AverageRating"
                    TotalRatings="@recipe.TotalRatings" />
    </div>

    <div class="row">
        <div class="col-md-5 mb-4">
            <div class="card">
                <div class="card-header fw-bold">Ingredients</div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-7 mb-4">
            <div class="card">
                <div class="card-header fw-bold">Steps</div>
                <ol class="list-group list-group-flush list-group-numbered">
                    @foreach (var step in recipe.Steps)
                    {
                        <li class="list-group-item">@step</li>
                    }
                </ol>
            </div>
        </div>
    </div>
}
else
{
    <PageTitle>Recipe Not Found</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/recipes" class="btn btn-primary">Browse Recipes</a>
}

@code {
    [Parameter] public int Id { get; set; }
    private RecipeShare.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted successfully!</strong>
        <a href="/recipes" class="alert-link">Browse recipes</a> to see it.
    </div>
}
else
{
    <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <div class="mb-3">
            <label for="title" class="form-label">Title</label>
            <InputText id="title" class="form-control" @bind-Value="submission.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in categories)
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="submission.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="submission.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeShare.Models.RecipeSubmission submission = new();
    private List<string> categories = new();
