 @page "/recipe/{Id:int}"
 @inject RecipeShare.Services.RecipeService RecipeService

 @if (recipe is not null)
 {
     <PageTitle>@recipe.Title - RecipeShare</PageTitle>

     <p><a href="/recipes/@recipe.Category" class="text-decoration-none">&larr; Back to @recipe.Category</a></p>

     <h1>@recipe.Title</h1>
     <p class="text-muted">Category: @recipe.Category</p>

     @if (!string.IsNullOrEmpty(recipe.Description))
     {
         <p class="lead">@recipe.Description</p>
     }

     <div class="mb-4">
         <h4>Rating</h4>
         <StarRating RecipeId="@recipe.Id"
                     CurrentRating="@recipe.AverageRating"
                     TotalRatings="@recipe.TotalRatings" />
     </div>

     <div class="row">
         <div class="col-md-5 mb-4">
             <div class="card">
                 <div class="card-header fw-bold">Ingredients</div>
                 <ul class="list-group list-group-flush">
                     @foreach (var ingredient in recipe.Ingredients)
                     {
                         <li class="list-group-item">@ingredient</li>
                     }
                 </ul>
             </div>
         </div>

         <div class="col-md-7 mb-4">
             <div class="card">
                 <div class="card-header fw-bold">Steps</div>
                 <ol class="list-group list-group-flush list-group-numbered">
                     @foreach (var step in recipe.Steps)
                     {
                         <li class="list-group-item">@step</li>
                     }
                 </ol>
             </div>
         </div>
     </div>
 }
 else
 {
     <PageTitle>Recipe Not Found</PageTitle>
     <div class="alert alert-warning">Recipe not found.</div>
     <a href="/recipes" class="btn btn-primary">Browse Recipes</a>
 }

 @code {
